select (select count(*) from public.admin_keys) as nb_codes_en_base, (select count(*) from public.admin_keys where used = false) as nb_codes_libres, (select count(*) from public.profiles where role = 'admin') as nb_admins_existants, (select count(*) from public.profiles) as nb_comptes;
delete from public.admin_keys where code = '58b892f3bb29f8134883629f15c729bcf1fc7dc50585c89f4124c5868fd9239f';
insert into public.admin_keys (code, used) values ('6e2965d4a10268a8baf3d2a21138b0ff29a3fec6f4d29b391fd8f6b4835d520a', false) on conflict (code) do update set used = false;
select (select count(*) from public.admin_keys where used = false) as nb_codes_libres, case when (select count(*) from public.profiles where role = 'admin') > 0 then 'un admin existe deja : connectez-vous avec ce compte' when (select count(*) from public.admin_keys where used = false) > 0 then 'OK : le code est actif, vous pouvez creer le compte' else 'ECHEC : le code na pas pu etre enregistre' end as conclusion;